Open <b>TextAssertions.groovy</b>. Delete the sample contents and paste this code. Then save with <b>Ctrl+S</b> (or <b>Cmd+S</b> on a Mac).<pre class="code">package customKeywords

import com.kms.katalon.core.annotation.Keyword
import com.kms.katalon.core.testobject.TestObject
import com.kms.katalon.core.webui.keyword.WebUiBuiltInKeywords as WebUI
import com.kms.katalon.core.model.FailureHandling

class TextAssertions {
    @Keyword
    def verifyTextEquals(TestObject element, String expectedText) {
        WebUI.verifyElementText(element, expectedText,
            FailureHandling.STOP_ON_FAILURE)
    }
}</pre><button class="btn g s" data-copy="1">📋 Copy code</button>

Open <b>BrowserListener.groovy</b>. Delete the sample contents and paste this code.<pre class="code">import com.kms.katalon.core.annotation.BeforeTestCase
import com.kms.katalon.core.annotation.AfterTestCase
import com.kms.katalon.core.context.TestCaseContext
import com.kms.katalon.core.webui.keyword.WebUiBuiltInKeywords as WebUI

class BrowserListener {
    @BeforeTestCase
    def openBrowser(TestCaseContext context) {
        WebUI.openBrowser('')
        WebUI.navigateToUrl('https://katalon-demo-cura.herokuapp.com/')
    }

    @AfterTestCase
    def closeBrowser(TestCaseContext context) {
        WebUI.closeBrowser()
    }
}</pre><button class="btn g s" data-copy="1">📋 Copy code</button>

Open an existing test case and switch to <b>Script</b> view. Add this Groovy code, or adapt the navigation step to your test.<pre class="code">import static com.kms.katalon.core.testobject.ObjectRepository.findTestObject
import internal.GlobalVariable
import com.kms.katalon.core.webui.keyword.WebUiBuiltInKeywords as WebUI

WebUI.openBrowser('')
try {
    WebUI.navigateToUrl(GlobalVariable.baseUrl)
    WebUI.verifyElementPresent(
        findTestObject('Object Repository/Page_CURA/button_MakeAppointment'), 10)
} finally {
    WebUI.closeBrowser()
}</pre><button class="btn g s" data-copy="1">📋 Copy code</button>

